7	
8	/// Reusable searchable single-select screen for profession, nationality, ethnicity.
9	/// Fetches options from API endpoint with a "Suggested" section.
10	class SearchableSingleSelectScreen extends ConsumerStatefulWidget {
11	  const SearchableSingleSelectScreen({
12	    super.key,
13	    required this.title,
14	    required this.apiPath,
15	    required this.onConfirm,
16	    this.suggestedApiPath,
17	    this.initialValue,
18	    this.itemLabel,
19	    this.itemIcon,
20	    this.isSkippable = false,
21	    this.onSkip,
22	    this.currentStep = 0,
23	    this.totalSteps = 14,
24	    this.helpText,
25	  });
26	
27	  final String title;
28	  final String apiPath; // e.g. '/professions'
29	  final String? suggestedApiPath; // e.g. '/professions/suggested'
30	  final void Function(dynamic selected) onConfirm;
31	  final dynamic initialValue;
32	  final String Function(dynamic item)? itemLabel;
33	  final Widget Function(dynamic item)? itemIcon;
34	  final bool isSkippable;
35	  final VoidCallback? onSkip;
36	  final int currentStep;
37	  final int totalSteps;
38	  final String? helpText;
39	
40	  @override
41	  ConsumerState<SearchableSingleSelectScreen> createState() => _SearchableSingleSelectScreenState();
42	}
43	
44	class _SearchableSingleSelectScreenState extends ConsumerState<SearchableSingleSelectScreen> {
45	  final _searchCtrl = TextEditingController();
46	  List<dynamic> _allItems = [];
47	  List<dynamic> _suggestedItems = [];
48	  List<dynamic> _filteredItems = [];
49	  dynamic _selected;
50	  bool _loading = true;
51	  String _query = '';
52	
53	  @override
54	  void initState() {
55	    super.initState();
56	    _selected = widget.initialValue;
57	    _loadData();
58	    _searchCtrl.addListener(_onSearchChanged);
59	  }
60	
61	  @override
62	  void dispose() {
63	    _searchCtrl.removeListener(_onSearchChanged);
64	    _searchCtrl.dispose();
65	    super.dispose();
66	  }
67	
68	  Future<void> _loadData() async {
69	    setState(() => _loading = true);
70	    try {
71	      final api = ref.read(apiProvider);
72	      final all = await api.get<List<dynamic>>(widget.apiPath, (j) => (j as List).cast<dynamic>());
73	      _allItems = all;
74	      _filteredItems = all;
75	
76	      if (widget.suggestedApiPath != null) {
77	        final suggested = await api.get<List<dynamic>>(widget.suggestedApiPath!, (j) => (j as List).cast<dynamic>());
78	        _suggestedItems = suggested;
79	      }
80	    } catch (e) {
81	      if (mounted) {
82	        ScaffoldMessenger.of(context).showSnackBar(
83	          SnackBar(content: Text('Failed to load options: $e')),
84	        );
85	      }
86	    } finally {
87	      if (mounted) setState(() => _loading = false);
88	    }
89	  }
90	
91	  void _onSearchChanged() {
