147	                  'Take a live selfie. We compare it with your main photo — this is what keeps Rishta free of fake profiles.',
148	                  textAlign: TextAlign.center,
149	                  style: Theme.of(context).textTheme.bodyMedium,
150	                ),
151	                const SizedBox(height: Tokens.spaceMd),
152	                if (error != null) ...[
