1	/// Shared JSON coercion. One place that knows how to read a field defensively,
2	/// so no model repeats null-handling and a backend type change surfaces here
3	/// rather than in twelve `fromJson` bodies.
4	abstract final class Json {
5	  static String str(Map<String, dynamic> j, String k, [String fallback = '']) =>
6	      j[k] as String? ?? fallback;
7	
8	  static String? optStr(Map<String, dynamic> j, String k) => j[k] as String?;
9	
10	  static int intg(Map<String, dynamic> j, String k, [int fallback = 0]) {
11	    final v = j[k];
12	    if (v is int) return v;
13	    if (v is num) return v.toInt();
14	    return int.tryParse('$v') ?? fallback;
15	  }
16	
17	  static double? optDouble(Map<String, dynamic> j, String k) {
18	    final v = j[k];
19	    if (v is num) return v.toDouble();
20	    return double.tryParse('$v');
21	  }
22	
23	  static bool flag(Map<String, dynamic> j, String k, [bool fallback = false]) =>
24	      j[k] as bool? ?? fallback;
25	
26	  static List<String> strings(Map<String, dynamic> j, String k) =>
27	      (j[k] as List<dynamic>? ?? const []).map((e) => '$e').toList(growable: false);
28	
29	  static DateTime? date(Map<String, dynamic> j, String k) =>
30	      DateTime.tryParse('${j[k]}')?.toLocal();
31	
32	  static T child<T>(Map<String, dynamic> j, String k, T Function(Map<String, dynamic>) fromJson) =>
33	      fromJson(j[k] as Map<String, dynamic>? ?? const {});
34	
35	  static List<T> children<T>(
36	    Map<String, dynamic> j,
37	    String k,
38	    T Function(Map<String, dynamic>) fromJson,
39	  ) =>
40	      (j[k] as List<dynamic>? ?? const [])
41	          .map((e) => fromJson(e as Map<String, dynamic>))
42	          .toList(growable: false);
43	}
44	
45	enum VerificationStatus {
46	  pending,
47	  verified,
48	  failed;
49	
50	  static VerificationStatus parse(String? v) => switch (v) {
51	        'verified' => VerificationStatus.verified,
52	        'failed' => VerificationStatus.failed,
53	        _ => VerificationStatus.pending,
54	      };
55	
56	  bool get isVerified => this == VerificationStatus.verified;
57	}
58	
59	class Tag {
60	  const Tag({required this.id, required this.label});
61	
62	  final int id;
63	  final String label;
64	
65	  factory Tag.fromJson(Map<String, dynamic> j) =>
66	      Tag(id: Json.intg(j, 'id'), label: Json.str(j, 'label'));
67	}
68	
69	/// What a feed card and a match row both need to render. The is-a relationship
70	/// is real — a feed card genuinely is a profile summary plus ranking metadata —
71	/// so the shared fields are declared once.
72	class ProfileSummary {
73	  const ProfileSummary({
74	    required this.userId,
75	    required this.photos,
76	    this.name,
77	    this.age,
78	    this.gender,
79	    this.location,
80	    this.bio = '',
81	    this.education,
82	    this.profession,
83	    this.maritalStatus,
84	    this.verification = VerificationStatus.pending,
85	  });
86	
87	  final String userId;
88	  final List<String> photos;
89	  final String? name;
90	  final int? age;
91	  final String? gender;
92	  final String? location;
93	  final String bio;
94	  final String? education;
95	  final String? profession;
96	  final String? maritalStatus;
97	  final VerificationStatus verification;
98	
99	  String? get primaryPhoto => photos.isEmpty ? null : photos.first;
100	
101	  String get displayName => name ?? location ?? 'Rishta member';
102	
